sql.where:
deleted_at is null
and source_type = #{query.sourceType}
and status = #{query.status}

deleted_at is null
and project_id = #{query.projectId}
and source_id = #{query.sourceId}
and source_type = #{query.sourceType}
and status = #{query.status}

deleted_at is null and import_id = #{query.importId} and status = #{query.status}
and lower(source_ref) like concat('%', lower(#{query.sourceRef}), '%')
and ( lower(title) like concat('%', lower(#{query.keyword}), '%') or lower(coalesce(description, '')) like concat('%', lower(#{query.keyword}), '%') or lower(coalesce(acceptance_criteria, '')) like concat('%', lower(#{query.keyword}), '%') or lower(coalesce(tags, '')) like concat('%', lower(#{query.keyword}), '%') or lower(coalesce(source_fragment, '')) like concat('%', lower(#{query.keyword}), '%') or lower(coalesce(external_requirement_id, '')) like concat('%', lower(#{query.keyword}), '%') )

deleted_at is null
and source_id = #{query.sourceId}
and source_code = #{query.sourceCode}
and event_type = #{query.eventType}
and status = #{query.status}
and received_at >= #{query.receivedFrom}
and received_at <= #{query.receivedTo}

mapper.select:
select 
from document_input_candidate
where import_id = #{importId}
  and deleted_at is null
order by created_at asc
limit #{size} offset #{offset}
